async def act(page):
    """
    Create a new Shopping Cart Price Rule for a Thanksgiving sale that gives $40 off
    at checkout for all customers.

    Notes:
    - Uses a relative goto to the Shopping Cart Price Rules index, then creates a
      new rule. The exact admin paths in Magento 1.x typically expose promo_quote
      controller for shopping cart rules.
    - The final action (clicking Save) may navigate away, so it is left as the
      last interaction.
    - The code uses multiple selection strategies and narrow checks to be robust
      if some controls render slightly differently.
    """

    # 1) Navigate to the Shopping Cart Price Rules list (relative path)
    await page.goto('/index.php/admin/promo_quote/')
    await page.wait_for_load_state('networkidle')

    # Helper to try multiple locator strategies for clicking an element.
    async def click_first_matching(locators):
        for loc in locators:
            try:
                count = await loc.count()
                if count and count > 0:
                    await loc.first.click()
                    return True
            except Exception:
                # Narrowly ignore single-locator failures and try the next
                continue
        return False

    # 2) Click the Add New Rule button
    add_new_locators = [
        page.get_by_role('button', name='Add New Rule'),
        page.get_by_role('link', name='Add New Rule'),
        page.get_by_role('button', name='Add New'),
        page.get_by_role('link', name='Add New')
    ]
    clicked = await click_first_matching(add_new_locators)
    if not clicked:
        # If the page lists a table with an Add button in a toolbar, try a more generic approach
        toolbar_add = page.get_by_role('button').filter(has_text='Add New')
        if await toolbar_add.count() > 0:
            await toolbar_add.first.click()
        else:
            raise RuntimeError('Unable to find Add New Rule control on promo_quote index')

    # Wait for the new rule form to appear. Try to wait for a sniffable field like Rule Name.
    rule_name_field = page.get_by_role('textbox', name='Rule Name')
    await rule_name_field.wait_for(timeout=5000)

    # 3) Fill in the main rule fields
    await rule_name_field.fill('Thanks giving sale')

    # Description (may be a textarea or textbox)
    desc_locator = page.get_by_role('textbox', name='Description')
    if await desc_locator.count() > 0:
        await desc_locator.fill('Thanksgiving promotion: $40 off at checkout for all customers')
    else:
        # try a textarea by label
        desc_textarea = page.get_by_role('textbox').filter(has_text='Description')
        if await desc_textarea.count() > 0:
            await desc_textarea.first.fill('Thanksgiving promotion: $40 off at checkout for all customers')

    # Status: set to Active
    status_combobox = page.get_by_role('combobox', name='Status')
    if await status_combobox.count() > 0:
        try:
            await status_combobox.select_option(label='Active')
        except Exception:
            # fallback: try by value
            await status_combobox.select_option(value='1')

    # Websites: try to select All Websites (if present)
    websites_combobox = page.get_by_role('combobox', name='Websites')
    if await websites_combobox.count() > 0:
        # Try common visible label
        try:
            await websites_combobox.select_option(label='All Websites')
        except Exception:
            # fallback to selecting the first option
            opts = await websites_combobox.evaluate('el => Array.from(el.options).map(o => o.value)')
            if opts:
                await websites_combobox.select_option(value=opts[0])

    # Customer Groups: check all groups so that rule applies to all customers
    # Look for a fieldset/group named 'Customer Groups' and check all checkboxes inside
    cust_group = page.get_by_role('group', name='Customer Groups')
    if await cust_group.count() > 0:
        checkboxes = cust_group.get_by_role('checkbox')
        n = await checkboxes.count()
        for i in range(n):
            cb = checkboxes.nth(i)
            try:
                is_checked = await cb.is_checked()
            except Exception:
                is_checked = False
            if not is_checked:
                await cb.check()
    else:
        # fallback: try to check any checkboxes near labels that look like customer groups
        all_checkboxes = page.get_by_role('checkbox')
        if await all_checkboxes.count() > 0:
            n = await all_checkboxes.count()
            for i in range(n):
                cb = all_checkboxes.nth(i)
                try:
                    if not await cb.is_checked():
                        await cb.check()
                except Exception:
                    continue

    # Coupon: choose No Coupon so discount auto-applies to cart (applies to all customers)
    coupon_combobox = page.get_by_role('combobox', name='Coupon')
    if await coupon_combobox.count() > 0:
        try:
            await coupon_combobox.select_option(label='No Coupon')
        except Exception:
            # Some installs use 'No coupon' or value-based selection
            try:
                await coupon_combobox.select_option(label='No coupon')
            except Exception:
                # leave as-is if can't set
                pass

    # Actions: set Apply to a fixed amount discount for the whole cart and set Discount Amount to 40
    apply_combobox = page.get_by_role('combobox', name='Apply')
    if await apply_combobox.count() > 0:
        # Try to pick an option that contains 'Fixed' (best-effort)
        try:
            await apply_combobox.select_option(label='Fixed amount discount for whole cart')
        except Exception:
            try:
                # try a shorter label
                await apply_combobox.select_option(label='Fixed')
            except Exception:
                # try selecting by an option value that may exist
                try:
                    opts = await apply_combobox.evaluate('el => Array.from(el.options).map(o => o.label)')
                    # find first option containing 'Fixed'
                    fixed_label = next((o for o in opts if 'Fixed' in o or 'fixed' in o), None)
                    if fixed_label:
                        await apply_combobox.select_option(label=fixed_label)
                except Exception:
                    pass

    # Discount Amount field (textbox)
    discount_locator = page.get_by_role('textbox', name='Discount Amount')
    if await discount_locator.count() > 0:
        await discount_locator.fill('40')
    else:
        # fallback: search for a textbox near the word 'Discount'
        all_textboxes = page.get_by_role('textbox')
        if await all_textboxes.count() > 0:
            # attempt to identify the discount field by placeholder or aria-label containing Discount
            n = await all_textboxes.count()
            filled = False
            for i in range(n):
                t = all_textboxes.nth(i)
                try:
                    label = await t.get_attribute('aria-label')
                except Exception:
                    label = None
                if label and 'Discount' in label:
                    await t.fill('40')
                    filled = True
                    break
            if not filled:
                # as a last resort, fill the first small numeric textbox
                for i in range(n):
                    t = all_textboxes.nth(i)
                    size = 0
                    try:
                        size = int(await t.evaluate('el => el.maxLength || 0'))
                    except Exception:
                        pass
                    # try to fill first textbox we can
                    try:
                        await t.fill('40')
                        break
                    except Exception:
                        continue

    # 4) Save the rule. The Save button will likely navigate away; leave as last action.
    save_locators = [
        page.get_by_role('button', name='Save Rule'),
        page.get_by_role('button', name='Save'),
        page.get_by_role('button').filter(has_text='Save')
    ]
    saved = await click_first_matching(save_locators)
    if not saved:
        raise RuntimeError('Unable to find Save control to finalize the new price rule')

    # After saving, wait briefly for the save to complete / navigation
    await page.wait_for_load_state('networkidle')

